ui.css:
.panel { position: relative; background: repeating-linear-gradient(0deg, rgba(0,0,0,.28) 0 1px, transparent 1px 3px), rgba(2,10,5,.9); border: 2px solid #2a994b; border-radius: 0; box-shadow: 0 0 0 3px #020a05, 0 0 14px rgba(77,219,118,.28), inset 0 0 18px rgba(77,219,118,.12); padding: 16px 16px 10px; font-family: 'VT323', monospace; color: #4ddb76; }
.panel::before { content: ' PWR '; position: absolute; left: 12px; top: -12px; padding: 0 6px; background: #020a05; font: 20px/1 'VT323', monospace; color: #ffb238; text-shadow: 0 0 6px rgba(255,178,56,.8); }
.bar { width: 210px; height: 18px; background: repeating-linear-gradient(90deg, rgba(122,74,14,.55) 0 8px, transparent 8px 10px); }
.bar-fill { height: 100%; background: repeating-linear-gradient(90deg, #ffb238 0 8px, transparent 8px 10px); filter: drop-shadow(0 0 5px rgba(255,178,56,.8)); transition: none; }
.big { font: 52px/0.95 'VT323', monospace; color: #a3ffbd; text-shadow: 0 0 6px rgba(77,219,118,.75), 0 0 16px rgba(77,219,118,.25); }
.cursor::after { content: '\2588'; animation: termblink 1.06s steps(1) infinite; }
@keyframes termblink { 0% { opacity: 1; } 50% { opacity: 0; } }
